root = std::make_shared<Node>('+', 0);
    int num_chars;
    infile.read(reinterpret_cast<char*>(&num_chars), sizeof(num_chars));

    for (int i = 0; i < num_chars; i++) {
        unsigned char ch;
        int code_length;
        infile.read(reinterpret_cast<char*>(&ch), sizeof(ch));
        infile.read(reinterpret_cast<char*>(&code_length), sizeof(code_length));

        std::string code(code_length, ' ');
        infile.read(&code[0], code_length);

        std::shared_ptr<Node> current = root;
        for (char bit : code) {
            if (bit == '0') {
                if (!current->left) {
                    current->left = std::make_shared<Node>('+', 0);
                }
                current = current->left;
            } else {
                if (!current->right) {
                    current->right = std::make_shared<Node>('+', 0);
                }
                current = current->right;
            }
        }
        current->character = ch;
        current->frequency = 1;
    }

